                    counts[(r + c) % period][value] += 1
                    total += 1

        mapping = [counter.most_common(1)[0][0] if counter else 1
                   for counter in counts]
        correct = sum(counter[mapping[i]] for i, counter in enumerate(counts))
        candidates.append((correct / total if total else 0, period, mapping))

    best_score = max(item[0] for item in candidates)
    score, period, mapping = min(
        (item for item in candidates if item[0] >= best_score - 0.02),
        key=lambda item: item[1]
