from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])

    # Infer the repeating color sequence from the interior, excluding the
    # top and left frame.
    counts = Counter(
        grid[r][c]
        for r in range(3, h)
        for c in range(3, w)
        if grid[r][c] != 0
    )
    palette = sorted(color for color, n in counts.items() if n >= 3)

    # Find the common step along rows in this ordered sequence.
    rank = {color: i for i, color in enumerate(palette)}
    steps = Counter()
    for r in range(3, h):
        for c in range(3, w - 1):
            a, b = grid[r][c], grid[r][c + 1]
            if a in rank and b in rank:
                steps[(rank[b] - rank[a]) % len(palette)] += 1
    step = steps.most_common(1)[0][0] if steps else 1
    p = len(palette)

    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if out[r][c] != 0:
                continue

            # Restore the outer background and the top/left frame.
            if r < 2 or c < 2:
                out[r][c] = 1
            elif r == 2 or c == 2:
                out[r][c] = 4
            else:
                # Continue the row's repeating sequence from a known cell.
                anchors = [
                    k for k in range(3, w)
                    if grid[r][k] in rank
                ]
                if anchors:
                    k = min(anchors, key=lambda x: abs(x - c))
                    idx = (rank[grid[r][k]] + step * (c - k)) % p
                    out[r][c] = palette[idx]
    return out
